#!/bin/sh
# Builds kaggle/adapter/kernel.py: carries src/adapter.py + fold ids (filename, fold number).
# GPU 0: Whisper-large-v3 frames -> adapter grader; GPU 1: WavLM-large frames -> adapter grader. 5 folds x 3 seeds each.
cd "$(dirname "$0")/.."
B64=$(base64 < src/adapter.py | tr -d '\n')
FOLDCSV=$(cut -d, -f1,2 cache/folds.csv | base64 | tr -d '\n')
cat > kaggle/adapter/kernel.py <<PY
# Kaggle kernel for Stage I (adapter graders). Generated by kaggle/build_adapter.sh from src/adapter.py.
import base64, glob, os, subprocess, sys, threading, time
import torch
from huggingface_hub import snapshot_download

OUT, TMP = "/kaggle/working", "/tmp/frames"
open("/tmp/adapter.py", "w").write(base64.b64decode("$B64").decode())
open("/tmp/folds.csv", "w").write(base64.b64decode("$FOLDCSV").decode())
DATA = os.path.dirname(glob.glob("/kaggle/input/**/train.csv", recursive=True)[0])
for m in ("openai/whisper-large-v3", "microsoft/wavlm-large"):
    snapshot_download(m, allow_patterns=["*.json", "*.safetensors", "*.txt", "*.bin"])
n = torch.cuda.device_count()
print("GPUs:", n, [torch.cuda.get_device_name(i) for i in range(n)], flush=True)
codes = {}

def run(enc, gpu):
    env = {**os.environ, "CUDA_VISIBLE_DEVICES": str(gpu)}
    py = [sys.executable, "/tmp/adapter.py"]
    r1 = subprocess.run(py + ["extract", "--data", DATA, "--out", TMP, "--encoder", enc], env=env)
    r2 = subprocess.run(py + ["train", "--feats", TMP, "--data", DATA, "--folds", "/tmp/folds.csv",
                              "--out", f"{OUT}/adapter_{enc}", "--encoder", enc], env=env) if r1.returncode == 0 else r1
    codes[enc] = (r1.returncode, r2.returncode)

t0 = time.time()
th = [threading.Thread(target=run, args=(e, g % max(1, n))) for g, e in enumerate(["whisper", "wavlm"])]
[t.start() for t in th]; [t.join() for t in th]
print("exit codes (extract, train):", codes, "| wall time %.0f min" % ((time.time() - t0) / 60), flush=True)
PY
echo "built kaggle/adapter/kernel.py"
